package com.econest.view;
import com.econest.model.*;import javax.swing.*;import java.awt.*;import java.awt.event.ActionListener;import java.util.List;
public class OrderPanel extends JPanel{
 private final JComboBox<Client> clientBox=new JComboBox<>();private final JComboBox<Product> productBox=new JComboBox<>();private final JSpinner qty=new JSpinner(new SpinnerNumberModel(1,1,10000,1));private final JComboBox<String> statusBox=new JComboBox<>(new String[]{"Pending","Confirmed","Cancelled","Completed"});
 private final JButton addItem=UiUtils.button("Add Product",UiUtils.PRIMARY),removeItem=UiUtils.button("Remove Product",UiUtils.DANGER),create=UiUtils.button("Create Order",UiUtils.PRIMARY),update=UiUtils.button("Update Order",UiUtils.PRIMARY),cancel=UiUtils.button("Cancel Order",UiUtils.DANGER),clear=UiUtils.button("Clear",UiUtils.NEUTRAL),search=UiUtils.button("Search",UiUtils.NEUTRAL),all=UiUtils.button("Show All",UiUtils.NEUTRAL);
 private final JLabel total=new JLabel("Total: 0.00");private final JTextField searchField=new JTextField(18);private final OrderTableModel orderModel=new OrderTableModel();private final OrderItemTableModel itemModel=new OrderItemTableModel();private final JTable orders=new JTable(orderModel),items=new JTable(itemModel);
 public OrderPanel(){setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(10,10,10,10));add(top(),BorderLayout.NORTH);add(split(),BorderLayout.CENTER);}
 private JPanel top(){JPanel p=new JPanel(new BorderLayout());JPanel f=new JPanel(new FlowLayout(FlowLayout.LEFT));f.setBorder(BorderFactory.createTitledBorder("Create / Update Order"));f.add(new JLabel("Client:"));f.add(clientBox);f.add(new JLabel("Product:"));f.add(productBox);f.add(new JLabel("Quantity:"));f.add(qty);f.add(addItem);f.add(removeItem);f.add(new JLabel("Status:"));f.add(statusBox);p.add(f,BorderLayout.CENTER);JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));b.add(create);b.add(update);b.add(cancel);b.add(clear);b.add(total);p.add(b,BorderLayout.SOUTH);return p;}
 private JSplitPane split(){items.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);orders.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);JPanel left=new JPanel(new BorderLayout());JPanel sb=new JPanel(new FlowLayout(FlowLayout.LEFT));sb.add(new JLabel("Search:"));sb.add(searchField);sb.add(search);sb.add(all);left.add(sb,BorderLayout.NORTH);left.add(new JScrollPane(orders),BorderLayout.CENTER);JPanel right=new JPanel(new BorderLayout());right.setBorder(BorderFactory.createTitledBorder("Order Items"));right.add(new JScrollPane(items),BorderLayout.CENTER);JSplitPane s=new JSplitPane(JSplitPane.VERTICAL_SPLIT,left,right);s.setResizeWeight(.55);return s;}
 public void setClients(List<Client>x){clientBox.removeAllItems();for(Client c:x)clientBox.addItem(c);}public void setProducts(List<Product>x){productBox.removeAllItems();for(Product p:x)productBox.addItem(p);}public Client getSelectedClient(){return(Client)clientBox.getSelectedItem();}public Product getSelectedProduct(){return(Product)productBox.getSelectedItem();}public int getQuantity(){return(Integer)qty.getValue();}public String getStatus(){return(String)statusBox.getSelectedItem();}public String getSearchText(){return searchField.getText();}
 public void addItem(){Product p=getSelectedProduct();if(p!=null){for(OrderItem i:itemModel.getItems())if(i.getProductId()==p.getId()){i.setQuantity(i.getQuantity()+getQuantity());itemModel.setItems(itemModel.getItems());updateTotal();return;}itemModel.add(new OrderItem(0,0,p.getId(),p.getName(),getQuantity(),p.calculatePrice()));updateTotal();}}
 public void removeItem(){int r=items.getSelectedRow();if(r>=0){itemModel.remove(r);updateTotal();}}
 public List<OrderItem> getItems(){return itemModel.getItems();}public void setItems(List<OrderItem>x){itemModel.setItems(x);updateTotal();}public void updateTotal(){double t=itemModel.getItems().stream().mapToDouble(OrderItem::getSubtotal).sum();total.setText(String.format("Total: %.2f",t));}
 public Order getSelectedOrder(){int r=orders.getSelectedRow();return r<0?null:orderModel.getOrderAt(r);}public void setOrders(List<Order>x){orderModel.setOrders(x);}public void populateOrder(Order o){clientBox.setSelectedItem(findClient(o.getClientId()));statusBox.setSelectedItem(o.getStatus());setItems(o.getItems());}private Client findClient(int id){for(int i=0;i<clientBox.getItemCount();i++)if(clientBox.getItemAt(i).getId()==id)return clientBox.getItemAt(i);return null;}
 public void clearForm(){itemModel.setItems(List.of());statusBox.setSelectedItem("Pending");orders.clearSelection();updateTotal();} 
 public void onAddItem(ActionListener l){addItem.addActionListener(l);}public void onRemoveItem(ActionListener l){removeItem.addActionListener(l);}public void onCreate(ActionListener l){create.addActionListener(l);}public void onUpdate(ActionListener l){update.addActionListener(l);}public void onCancel(ActionListener l){cancel.addActionListener(l);}public void onClear(ActionListener l){clear.addActionListener(l);}public void onSearch(ActionListener l){search.addActionListener(l);searchField.addActionListener(l);}public void onShowAll(ActionListener l){all.addActionListener(l);}public void onRowSelected(Runnable r){orders.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting())r.run();});}
 public void showMessage(String m){JOptionPane.showMessageDialog(this,m,"EcoNest",JOptionPane.INFORMATION_MESSAGE);}public void showError(String m){JOptionPane.showMessageDialog(this,m,"Error",JOptionPane.ERROR_MESSAGE);}public boolean confirm(String m){return JOptionPane.showConfirmDialog(this,m,"Please confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
}
